export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-che-0001", "section": "service", "who": "reader", "text": "В СРЕДУ СВЕТЛЫЯ СЕДМИЦЫ ВЕЧЕРА По 9-м часе, во светильничном, облачится настоятель во всю священную одежду. И став пред святою трапезою с кадильницею, знаменует крестовидно, и возглашает глаголя:"},
  {"id": "cu-che-0002", "section": "service", "who": "reader", "text": "Благослове́н Бог наш всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-che-0003", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-che-0004", "section": "service", "who": "reader", "text": "Ами́нь."},
  {"id": "cu-che-0005", "section": "service", "who": "rubric", "text": "И той начинает:"},
  {"id": "cu-che-0006", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0007", "section": "service", "who": "rubric", "text": "Трижды. И мы тойжде отвещаем трижды."},
  {"id": "cu-che-0008", "section": "service", "who": "reader", "text": "И глаголет настоятель преждереченныя стихи: Первый стих:"},
  {"id": "cu-che-0009", "section": "service", "who": "reader", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-che-0010", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь:"},
  {"id": "cu-che-0011", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых:"},
  {"id": "cu-che-0012", "section": "service", "who": "rubric", "text": "Весь по единожды."},
  {"id": "cu-che-0013", "section": "service", "who": "rubric", "text": "Вторый стих:"},
  {"id": "cu-che-0014", "section": "service", "who": "reader", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-che-0015", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-che-0016", "section": "service", "who": "reader", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-che-0017", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-che-0018", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-che-0019", "section": "service", "who": "reader", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-che-0020", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-che-0021", "section": "service", "who": "reader", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-che-0022", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-che-0023", "section": "service", "who": "reader", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-che-0024", "section": "service", "who": "reader", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-che-0025", "section": "service", "who": "rubric", "text": "Таже настоятель:"},
  {"id": "cu-che-0026", "section": "service", "who": "reader", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы конец:"},
  {"id": "cu-che-0027", "section": "service", "who": "reader", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0028", "section": "service", "who": "rubric", "text": "Таже ектениа великая от диакона:"},
  {"id": "cu-che-0029", "section": "service", "who": "deacon", "text": "Ми́ром Го́споду помо́лимся."},
  {"id": "cu-che-0030", "section": "service", "who": "rubric", "text": "Подобает ведати, яко по внегда начати иерею, кадит святую трапезу по обычаю и весь олтарь, вечер, на"},
  {"id": "cu-che-0031", "section": "service", "who": "deacon", "text": "Го́споди воззва́х:"},
  {"id": "cu-che-0032", "section": "service", "who": "rubric", "text": "на Утрени, в начале канона исходит и кадит храм и лики и братию по обыкновенному чину."},
  {"id": "cu-che-0033", "section": "service", "who": "choir", "text": "На Го́споди воззва́х: поставим стихов 6. И поем стихиры воскресны 3, глас 5. Стих:"},
  {"id": "cu-che-0034", "section": "service", "who": "choir", "text": "А́ще беззако́ния на́зриши, Го́споди, Го́споди, кто постои́т? Я́ко у Тебе́ очище́ние есть."},
  {"id": "cu-che-0035", "section": "service", "who": "choir", "text": "Честны́м Твои́м Кресто́м, Христе́, / диа́вола посрами́л еси́, / и Воскресе́нием Твои́м жало грехо́вное притупи́л еси́, / и спасл еси́ ны от врат сме́ртных: / сла́вим Тя, Единоро́дне. Стих:"},
  {"id": "cu-che-0036", "section": "service", "who": "choir", "text": "И́мене ра́ди Твоего́ потерпе́х Тя, Го́споди, потерпе́ душа́ моя́ в сло́во Твое́, упова́ душа́ моя́ на Го́спода."},
  {"id": "cu-che-0037", "section": "service", "who": "choir", "text": "Воскресе́ние дая́й ро́ду челове́ческому, / я́ко овча́ на заколе́ние веде́ся, / устраши́шася сего́ кня́зи а́дстии, / и взя́шася врата́ плаче́вная. / Вни́де бо Царь сла́вы Христо́с, / глаго́ля су́щим во у́зах, изыди́те: / и су́щим во тьме, откры́йтеся. Стих:"},
  {"id": "cu-che-0038", "section": "service", "who": "choir", "text": "От стра́жи у́тренния до но́щи, от стра́жи у́тренния да упова́ет Изра́иль на Го́спода."},
  {"id": "cu-che-0039", "section": "service", "who": "choir", "text": "Ве́лие чу́до, / неви́димых Соде́тель, за человеколю́бие пло́тию пострада́в, / воскре́се Безсме́ртный. / Прииди́те оте́чествия язы́к, Тому́ поклони́мся: / благоутро́бием бо Его́ от пре́лести изба́вльшеся, / в Трие́х Ипоста́сех Еди́наго Бо́га пе́ти навыко́хом."},
  {"id": "cu-che-0040", "section": "service", "who": "choir", "text": "И восточны (Анатолиевы) 3, глас тойже. Стих:"},
  {"id": "cu-che-0041", "section": "service", "who": "choir", "text": "Я́ко у Го́спода ми́лость, и мно́гое у Него́ избавле́ние, и Той изба́вит Изра́иля от всех беззако́ний eго́."},
  {"id": "cu-che-0042", "section": "service", "who": "choir", "text": "Вече́рнее поклоне́ние / прино́сим Тебе́, Невече́рнему Све́ту, / на коне́ц веко́в, я́ко в зерца́ле пло́тию возсия́вшему мiрови, / и да́же до а́да низше́дшему, / и та́мо су́щую тьму разруши́вшему, / и свет Воскресе́ния язы́ком показа́вшему: / Светода́вче Го́споди, сла́ва Тебе́. Стих:"},
  {"id": "cu-che-0043", "section": "service", "who": "choir", "text": "Хвали́те Го́спода вси язы́цы, похвали́те Его́ вси лю́дие."},
  {"id": "cu-che-0044", "section": "service", "who": "choir", "text": "Нача́льника спасе́ния на́шего, / Христа́ славосло́вим: / Тому́ бо из ме́ртвых воскре́сшу, / мiр от пре́лести спасе́н бысть. / Ра́дуется лик А́нгельский, / бе́гает де́монов пре́лесть, / Ада́м пады́й воста́, / диа́вол упраздни́ся. Стих:"},
  {"id": "cu-che-0045", "section": "service", "who": "choir", "text": "Я́ко утверди́ся ми́лость Его́ на нас, и и́стина Госпо́дня пребыва́ет во век."},
  {"id": "cu-che-0046", "section": "service", "who": "choir", "text": "И́же от кустоди́и науче́ни быва́ху от беззако́нник, / покры́йте Христо́во Воста́ние, / и приими́те сре́бреники, и рцы́те / я́ко нам спя́щим, из гро́ба укра́ден бысть Ме́ртвый. / Кто ви́де, кто слы́ша, мертвеца́ укра́дена когда́, / па́че же пома́зана и на́га, / оста́вльша и во гро́бе погреба́льная Своя́? / Не прельща́йтеся иуде́е, / навы́кните рече́нием проро́ческим, и уразуме́йте, / я́ко Той есть вои́стинну Изба́витель мiра, и Всеси́льный."},
  {"id": "cu-che-0047", "section": "service", "who": "choir", "text": "Слава: Го́споди, ад плени́вый, / и смерть попра́вый, Спа́се наш, / просвети́вый мiр Кресто́м честны́м, / поми́луй нас."},
  {"id": "cu-che-0048", "section": "service", "who": "choir", "text": "И ныне, Богородичен: В Чермне́м мо́ри, / Неискусобра́чныя Неве́сты о́браз написа́ся иногда́: / та́мо Моисе́й, раздели́тель воды́: / зде же Гаврии́л, служи́тель чудесе́. / Тогда́ глубину́ ше́ствова немо́кренно Изра́иль; / ны́не же Христа́ роди́ безсе́менно Де́ва. / Мо́ре по проше́ствии Изра́илеве пребы́сть непрохо́дно; / Непоро́чная по Рождестве́ Эмману́илеве пребы́сть Нетле́нна. / Сый, и пре́жде Сый, / явле́йся, я́ко Челове́к, / Бо́же поми́луй нас."},
  {"id": "cu-che-0049", "section": "service", "who": "choir", "text": "Вход с кадилом. Све́те ти́хий:"},
  {"id": "cu-che-0050", "section": "service", "who": "rubric", "text": "И прокимен, глас 7:"},
  {"id": "cu-che-0051", "section": "service", "who": "choir", "text": "Внуши́, Бо́же, моли́тву мою́, / и не пре́зри моле́ния моего́. Стих:"},
  {"id": "cu-che-0052", "section": "service", "who": "choir", "text": "Вонми́ ми и услы́ши мя. Стих:"},
  {"id": "cu-che-0053", "section": "service", "who": "choir", "text": "Я́ко уклони́ша на мя беззако́ние. Стих:"},
  {"id": "cu-che-0054", "section": "service", "who": "choir", "text": "Аз к Бо́гу воззва́х, и Госпо́дь услы́ша мя. Ве́чер и зау́тра, и полу́дне. Таже:"},
  {"id": "cu-che-0055", "section": "service", "who": "choir", "text": "Внуши́, Бо́же, моли́тву мою́, и не пре́зри моле́ния моего́."},
  {"id": "cu-che-0056", "section": "service", "who": "rubric", "text": "Посем ектениа:"},
  {"id": "cu-che-0057", "section": "service", "who": "choir", "text": "Рцем вси: и Сподо́би, Го́споди, в ве́чер сей: Таже:"},
  {"id": "cu-che-0058", "section": "service", "who": "choir", "text": "Испо́лним вече́рнюю моли́тву:"},
  {"id": "cu-che-0059", "section": "service", "who": "choir", "text": "На стиховне, стихира воскресна, глас 5:"},
  {"id": "cu-che-0060", "section": "service", "who": "choir", "text": "Тебе́, Воплоще́ннаго Спа́са Христа́, / и Небе́с неразлучи́вшася, / во гла́сех пе́ний велича́ем, / я́ко Крест и смерть прия́л еси́ за род наш, / я́ко Человеколю́бец Госпо́дь, / испрове́ргий а́дова врата́, / тридне́вно воскре́сл еси́, / спаса́я ду́ши на́ша."},
  {"id": "cu-che-0061", "section": "service", "who": "choir", "text": "Таже стихиры Пасхи, глас 5. Стих:"},
  {"id": "cu-che-0062", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, / и расточа́тся врази́ Его́."},
  {"id": "cu-che-0063", "section": "service", "who": "choir", "text": "Па́сха / свяще́нная нам днесь показа́ся; / Па́сха но́ва свята́я; / Па́сха та́инственная; / Па́сха всечестна́я. / Па́сха Христо́с Изба́витель; / Па́сха непоро́чная; / Па́сха вели́кая; / Па́сха ве́рных. / Па́сха две́ри ра́йския нам отверза́ющая. / Па́сха всех освяща́ющая ве́рных. Стих:"},
  {"id": "cu-che-0064", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, / да исче́знут."},
  {"id": "cu-che-0065", "section": "service", "who": "choir", "text": "Прииди́те / от виде́ния жены́ благове́стницы, / и Сио́ну рцы́те: / приими́ / от нас ра́дости благове́щения, Воскресе́ния Христо́ва: / красу́йся, лику́й / и ра́дуйся, Иерусали́ме, / Царя́ Христа́ узре́в из гро́ба, / я́ко жениха́ происходя́ща. Стих:"},
  {"id": "cu-che-0066", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся."},
  {"id": "cu-che-0067", "section": "service", "who": "choir", "text": "Мироно́сицы жены́, / у́тру глубоку́, / предста́вша гро́бу Живода́вца, / обрето́ша А́нгела / на ка́мени седя́ща, / и той провеща́в им, / си́це глаго́лаше: / что и́щете Жива́го с ме́ртвыми; / что пла́чете Нетле́ннаго во тли? / Ше́дше, пропове́дите ученико́м Его́. Стих:"},
  {"id": "cu-che-0068", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори Госпо́дь, / возра́дуемся и возвесели́мся в онь."},
  {"id": "cu-che-0069", "section": "service", "who": "choir", "text": "Па́сха кра́сная, / Па́сха, Госпо́дня Па́сха! / Па́сха всечестна́я / нам возсия́. Па́сха, / ра́достию друг дру́га обы́мем. / О Па́сха! / Избавле́ние ско́рби, / и́бо из гро́ба днесь, / я́ко от черто́га / возсия́в Христо́с, / жены́ ра́дости испо́лни, глаго́ля: / пропове́дите апо́столом."},
  {"id": "cu-che-0070", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0071", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-che-0072", "section": "service", "who": "rubric", "text": "трижды, кроме конца стихиры."},
  {"id": "cu-che-0073", "section": "service", "who": "rubric", "text": "Таже диакон:"},
  {"id": "cu-che-0074", "section": "service", "who": "deacon", "text": "Прему́дрость. Мы же:"},
  {"id": "cu-che-0075", "section": "service", "who": "deacon", "text": "Благослови́. Настоятель:"},
  {"id": "cu-che-0076", "section": "service", "who": "deacon", "text": "Сый благослове́н Христо́с Бог наш: И мы:"},
  {"id": "cu-che-0077", "section": "service", "who": "deacon", "text": "Утверди́, Бо́же:"},
  {"id": "cu-che-0078", "section": "service", "who": "rubric", "text": "Таже настоятель, вместо: Слава Тебе Христе Боже:"},
  {"id": "cu-che-0079", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы:"},
  {"id": "cu-che-0080", "section": "service", "who": "deacon", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0081", "section": "service", "who": "rubric", "text": "И абие глаголет отпуст со Крестом:"},
  {"id": "cu-che-0082", "section": "service", "who": "deacon", "text": "Христо́с воскресы́й из ме́ртвых:"},
  {"id": "cu-che-0083", "section": "service", "who": "rubric", "text": "И прочее, якоже изъявися в конец Утрени."},
  {"id": "cu-che-0084", "section": "service", "who": "rubric", "text": "И целуем святыя иконы. И входим в трапезу, и глаголем:"},
  {"id": "cu-che-0085", "section": "service", "who": "deacon", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0086", "section": "service", "who": "deacon", "text": "Сла́ва, и ны́не: Настоятель:"},
  {"id": "cu-che-0087", "section": "service", "who": "deacon", "text": "Христе́ Бо́же благослови́:"},
  {"id": "cu-che-0088", "section": "service", "who": "rubric", "text": "По востании же от трапезы, глаголем:"},
  {"id": "cu-che-0089", "section": "service", "who": "deacon", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0090", "section": "service", "who": "deacon", "text": "Сла́ва, и ны́не: Настоятель:"},
  {"id": "cu-che-0091", "section": "service", "who": "deacon", "text": "С на́ми Бог Своею благодатию:"},
  {"id": "cu-che-0092", "section": "service", "who": "deacon", "text": "В ЧЕТВЕРТОК СВЕТЛЫЯ СЕДМИЦЫ НА УТРЕНИ"},
  {"id": "cu-che-0093", "section": "service", "who": "deacon", "text": "Прежде начала, вжигает кандила и свещи параекклисиарх. Таже клеплет в великий кампан, и в прочия. И собравшимся нам во храм, иерей полагает обычный поклон настоятелю, и отходит во святый олтарь, и взем кадильницу стоит пред святою Трапезою, кроме убо священническия одежды, епитрахилий точию возложь сверх мантии, кадит крестообразно, глаголя:"},
  {"id": "cu-che-0094", "section": "service", "who": "deacon", "text": "Сла́ва Святе́й, и Единосу́щней, и Животворя́щей, и Нераздели́мей Тро́ице, всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-che-0095", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-che-0096", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-che-0097", "section": "service", "who": "choir", "text": "Начинает настоятель, с прочими служители, велегласно настоящий тропарь, во глас 5:"},
  {"id": "cu-che-0098", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0099", "section": "service", "who": "choir", "text": "И мы тойжде поем подобне, со сладкопением. Поется же сей тропарь трижды от настоятеля, и трижды от нас."},
  {"id": "cu-che-0100", "section": "service", "who": "choir", "text": "Таже настоятель глаголет стихи: Первый стих:"},
  {"id": "cu-che-0101", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-che-0102", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь весь по единожды:"},
  {"id": "cu-che-0103", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: Вторый стих:"},
  {"id": "cu-che-0104", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-che-0105", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды. Третий стих:"},
  {"id": "cu-che-0106", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-che-0107", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-che-0108", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-che-0109", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-che-0110", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-che-0111", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-che-0112", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-che-0113", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-che-0114", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-che-0115", "section": "service", "who": "rubric", "text": "Таже настоятель:"},
  {"id": "cu-che-0116", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы конец:"},
  {"id": "cu-che-0117", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0118", "section": "service", "who": "choir", "text": "В мирских же храмех облачится иерей в ризы. Таже ектениа великая."},
  {"id": "cu-che-0119", "section": "service", "who": "rubric", "text": "И по возгласе абие поем канон, ирмос:"},
  {"id": "cu-che-0120", "section": "service", "who": "choir", "text": "Воскресе́ния день:"},
  {"id": "cu-che-0121", "section": "service", "who": "rubric", "text": "по дважды, тропари же на 10, с припевы:"},
  {"id": "cu-che-0122", "section": "service", "who": "choir", "text": "Христо́с воскре́се: В Сла́ва, и ны́не:"},
  {"id": "cu-che-0123", "section": "service", "who": "rubric", "text": "глаголем Богородичны господина Феофана, и господина Иосифа. Катавасия оба лика вкупе:"},
  {"id": "cu-che-0124", "section": "service", "who": "choir", "text": "Воскресе́ния день: И последи:"},
  {"id": "cu-che-0125", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0126", "section": "service", "who": "choir", "text": "Канон, глас 1. Песнь 1. Ирмос:"},
  {"id": "cu-che-0127", "section": "service", "who": "choir", "text": "Воскресе́ния день, / просвети́мся, лю́дие. / Па́сха, Госпо́дня Па́сха, / от сме́рти бо к жи́зни, / и от земли́ к небеси́, / Христо́с Бог нас преведе́, / побе́дную пою́щия. Припев:"},
  {"id": "cu-che-0128", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0129", "section": "service", "who": "choir", "text": "Очи́стим чу́вствия, и у́зрим / непристу́пным све́том / Воскресе́ния, Христа́ блиста́ющася, / и ра́дуйтеся, реку́ща, / я́сно да услы́шим, / побе́дную пою́ще. Припев:"},
  {"id": "cu-che-0130", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0131", "section": "service", "who": "choir", "text": "Небеса́ у́бо досто́йно да веселя́тся, / земля́ же да ра́дуется, / да пра́зднует же мир, / ви́димый же весь и неви́димый: / Христо́с бо воста́, / весе́лие ве́чное."},
  {"id": "cu-che-0132", "section": "service", "who": "choir", "text": "Иный канон Богородичен, подобен. Егоже краестрочие на первых тропарех: Феофа́нус. Глас тойже."},
  {"id": "cu-che-0133", "section": "service", "who": "choir", "text": "Слава: Умерщвле́ния преде́л сломи́ла еси́, / ве́чную жизнь ро́ждшая Христа́, из гро́ба возсия́вшаго днесь, / Де́во Всенепоро́чная, и мир просвети́вшаго."},
  {"id": "cu-che-0134", "section": "service", "who": "choir", "text": "И ныне: Воскре́сшаго ви́девши Сы́на Твоего́ и Бо́га, / ра́дуйся со апо́столы Богоблагода́тная Чи́стая, / и е́же ра́дуйся пе́рвее, я́ко всех ра́дости вина́, / восприя́ла еси́, Богома́ти Всенепоро́чная."},
  {"id": "cu-che-0135", "section": "service", "who": "rubric", "text": "Катавасия оба лика вкупе:"},
  {"id": "cu-che-0136", "section": "service", "who": "choir", "text": "Воскресе́ния день: И последи:"},
  {"id": "cu-che-0137", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0138", "section": "service", "who": "choir", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-che-0139", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое, / не от ка́мене непло́дна чудоде́емое, / но нетле́ния исто́чник / из гро́ба одожди́вша Христа́, / в Не́мже утвержда́емся. Припев:"},
  {"id": "cu-che-0140", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0141", "section": "service", "who": "choir", "text": "Ны́не вся испо́лнишася све́та, / не́бо же и земля́, и преиспо́дняя: / да пра́зднует у́бо вся тварь / воста́ние Христо́во, / в не́мже утвержда́ется. Припев:"},
  {"id": "cu-che-0142", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0143", "section": "service", "who": "choir", "text": "Вчера́ спогребо́хся Тебе́ Христе́, / совостаю́ днесь / воскре́сшу Тебе́, / сраспина́хся Тебе́ вчера́, / Сам мя спросла́ви Спа́се во Ца́рствии Твое́м."},
  {"id": "cu-che-0144", "section": "service", "who": "choir", "text": "Слава: На нетле́нную жизнь / прихожду́ днесь бла́гостию ро́ждшагося из Тебе́, Чи́стая, / и всем конце́м свет облиста́вшаго."},
  {"id": "cu-che-0145", "section": "service", "who": "choir", "text": "И ныне: Бо́га, Его́же родила́ еси́ пло́тию, из ме́ртвых, / я́коже рече́, воста́вша ви́девши, Чи́стая, лику́й, / и Сего́ я́ко Бо́га Пречи́стая возвелича́й. Катавасия:"},
  {"id": "cu-che-0146", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое: И тропарь:"},
  {"id": "cu-che-0147", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0148", "section": "service", "who": "choir", "text": "Таже ектениа."},
  {"id": "cu-che-0149", "section": "service", "who": "choir", "text": "Ипакои, глас 4:"},
  {"id": "cu-che-0150", "section": "service", "who": "choir", "text": "Предвари́вшия у́тро я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго, / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-che-0151", "section": "service", "who": "choir", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-che-0152", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи / богоглаго́ливый Авваку́м / да ста́нет с на́ми и пока́жет / светоно́сна А́нгела / я́сно глаго́люща: / днесь спасе́ние ми́ру, / я́ко воскре́се Христо́с, / я́ко всеси́лен. Припев:"},
  {"id": "cu-che-0153", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0154", "section": "service", "who": "choir", "text": "Му́жеский у́бо пол, / я́ко разве́рзый де́вственную утро́бу, / яви́ся Христо́с, / я́ко челове́к же, / А́гнец нарече́ся, / непоро́чен же, / я́ко невку́сен скве́рны, / на́ша Па́сха, / и я́ко Бог и́стинен / соверше́н рече́ся. Припев:"},
  {"id": "cu-che-0155", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0156", "section": "service", "who": "choir", "text": "Я́ко единоле́тный а́гнец, / благослове́нный нам вене́ц Христо́с, / во́лею за всех закла́н бысть, / Па́сха чисти́тельная, / и па́ки из гро́ба кра́сное / пра́вды нам возсия́ Со́лнце. Припев:"},
  {"id": "cu-che-0157", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0158", "section": "service", "who": "choir", "text": "Богооте́ц у́бо Дави́д / пред се́нным ковче́гом скака́ше игра́я, / лю́дие же Бо́жии святи́и, / образо́в сбытие́ зря́ще, / весели́мся Боже́ственне, / я́ко воскре́се Христо́с, / я́ко Всеси́лен."},
  {"id": "cu-che-0159", "section": "service", "who": "choir", "text": "Слава: Созда́вый Ада́ма, Твоего́ пра́отца, Чи́стая, / зи́ждется от Тебе́, и сме́ртное жили́ще разори́ Свое́ю сме́ртию днесь, / и озари́ вся / боже́ственными блиста́ньми Воскресе́ния."},
  {"id": "cu-che-0160", "section": "service", "who": "choir", "text": "И ныне: Его́же родила́ еси́ Христа́, / прекра́сно из ме́ртвых возсия́вша, Чи́стая зря́щи, / до́брая и непоро́чная в жена́х и кра́сная, / днесь во спасе́ние всех, со апо́столы ра́дующися, / Того́ прославля́й. Катавасия:"},
  {"id": "cu-che-0161", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи: И тропарь:"},
  {"id": "cu-che-0162", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0163", "section": "service", "who": "choir", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-che-0164", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́, / и вме́сто ми́ра песнь принесе́м Влады́це, / и Христа́ у́зрим / пра́вды Со́лнце, / всем жизнь возсия́юща. Припев:"},
  {"id": "cu-che-0165", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0166", "section": "service", "who": "choir", "text": "Безме́рное Твое́ благоутро́бие, / а́довыми у́зами содержи́мии зря́ще, / к све́ту идя́ху Христе́, / весе́лыми нога́ми, / Па́сху хва́ляще ве́чную. Припев:"},
  {"id": "cu-che-0167", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0168", "section": "service", "who": "choir", "text": "Присту́пим свещено́снии, / исходя́щу Христу́ из гро́ба, я́ко жениху́, / и спра́зднуем любопра́зднственными чи́нми / Па́сху Бо́жию спаси́тельную."},
  {"id": "cu-che-0169", "section": "service", "who": "choir", "text": "Слава: Просвеща́ется боже́ственными луча́ми и живоно́сными / воскресе́ния Сы́на Твоего́, Богома́ти Пречи́стая, / и ра́дости исполня́ется / благочести́вых собра́ние."},
  {"id": "cu-che-0170", "section": "service", "who": "choir", "text": "И ныне: Не разве́рзл еси́ врата́ де́вства в воплоще́нии, / гро́ба не разруши́л еси́ печа́тей, Царю́ созда́ния, / отону́дуже воскре́сшаго Тя зря́щи / Ма́ти, ра́довашеся. Катавасия:"},
  {"id": "cu-che-0171", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́: И тропарь:"},
  {"id": "cu-che-0172", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0173", "section": "service", "who": "choir", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-che-0174", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́, / и сокруши́л еси́ вереи́ ве́чныя, / содержа́щия свя́занныя, Христе́, / и тридне́вен, я́ко от ки́та Ио́на, / воскре́сл еси́ от гро́ба. Припев:"},
  {"id": "cu-che-0175", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0176", "section": "service", "who": "choir", "text": "Сохрани́в це́ла зна́мения Христе́, / воскре́сл еси́ от гро́ба, / ключи́ Де́вы не вреди́вый в рождестве́ Твое́м, / и отве́рзл еси́ нам ра́йския две́ри. Припев:"},
  {"id": "cu-che-0177", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0178", "section": "service", "who": "choir", "text": "Спа́се мой, / живо́е же и неже́ртвенное заколе́ние, / я́ко Бог Сам Себе́ / во́лею приве́л Отцу́, / совоскреси́л еси́ всеро́днаго Ада́ма, / воскре́с от гро́ба."},
  {"id": "cu-che-0179", "section": "service", "who": "choir", "text": "Слава: Возведе́ся дре́вле держи́мое сме́ртию и тле́нием, / воплоти́вшимся от Твоего́ пречи́стаго чре́ва, / к нетле́нней и присносу́щней жи́зни, / Богоро́дице Де́во."},
  {"id": "cu-che-0180", "section": "service", "who": "choir", "text": "И ныне: Сни́де в преиспо́дняя земли́, / в ложесна́ Твоя́, Чи́стая, сше́дый, / и всели́выйся и воплоти́выйся па́че ума́, / и воздви́же с Собо́ю Ада́ма, / воскре́с от гро́ба. Катавасия:"},
  {"id": "cu-che-0181", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́: И тропарь:"},
  {"id": "cu-che-0182", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0183", "section": "service", "who": "choir", "text": "Ектениа."},
  {"id": "cu-che-0184", "section": "service", "who": "choir", "text": "Таже кондак, глас 8:"},
  {"id": "cu-che-0185", "section": "service", "who": "choir", "text": "А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко победитель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся, / и Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние. Икос:"},
  {"id": "cu-che-0186", "section": "service", "who": "choir", "text": "Е́же пре́жде со́лнца Со́лнце заше́дшее иногда́ во гроб, / предвари́ша ко у́тру, и́щущия я́ко дне мvроно́сицы де́вы, / и друга́ ко друзе́й вопия́ху: / о други́ни! Прииди́те, воня́ми пома́жем те́ло живоно́сное и погребе́ное, / плоть воскреси́вшаго па́дшаго Ада́ма, лежа́щую во гро́бе. / И́дем, потщи́мся я́коже волсви́, и поклони́мся, / и принесе́м мvра я́ко да́ры, не в пелена́х, но в плащани́це обви́тому, / и пла́чим, и возопии́м: о Влады́ко, воста́ни, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-che-0187", "section": "service", "who": "choir", "text": "И чтение."},
  {"id": "cu-che-0188", "section": "service", "who": "choir", "text": "Таже глаголем:"},
  {"id": "cu-che-0189", "section": "service", "who": "choir", "text": "Воскресе́ние Христо́во ви́девше, / поклони́мся Свято́му Го́споду Иису́су, / еди́ному безгре́шному, / Кресту́ Твоему́ покланя́емся, Христе́, / и свято́е Воскресе́ние Твое́ пое́м и сла́вим: / Ты бо еси́ Бог наш, / ра́зве Тебе́ ино́го не зна́ем, / и́мя Твое́ имену́ем. / Прииди́те вси ве́рнии, / поклони́мся Свято́му Христо́ву Воскресе́нию: / се бо прии́де Кресто́м ра́дость всему́ ми́ру. / Всегда́ благословя́ще Го́спода, / пое́м Воскресе́ние Его́: / распя́тие бо претерпе́в, / сме́ртию смерть разруши́. [Трижды.]"},
  {"id": "cu-che-0190", "section": "service", "who": "choir", "text": "Воскре́с Иису́с от гро́ба, / я́коже прорече́, / даде́ нам живо́т ве́чный / и ве́лию ми́лость. [Трижды.]"},
  {"id": "cu-che-0191", "section": "service", "who": "choir", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-che-0192", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый, / быв Челове́к, / стра́ждет я́ко сме́ртен, / и стра́стию сме́ртное, / в нетле́ния облачи́т благоле́пие, / Еди́н благослове́н / отце́в Бог, и препросла́влен. Припев:"},
  {"id": "cu-che-0193", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0194", "section": "service", "who": "choir", "text": "Жены́ с ми́ры богому́дрыя в след Тебе́ теча́ху, / Его́же, я́ко ме́ртва, со слеза́ми иска́ху, / поклони́шася ра́дующияся Живо́му Бо́гу, / и Па́сху та́йную / Твои́м, Христе́, ученико́м благовести́ша. Припев:"},
  {"id": "cu-che-0195", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0196", "section": "service", "who": "choir", "text": "Сме́рти пра́зднуем умерщвле́ние, / а́дово разруше́ние, / ино́го жития́ ве́чнаго нача́ло, / и игра́юще пое́м Вино́внаго, / Еди́наго благослове́ннаго / отце́в Бо́га, и препросла́вленнаго. Припев:"},
  {"id": "cu-che-0197", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0198", "section": "service", "who": "choir", "text": "Я́ко вои́стинну свяще́нная, / и всепра́зднственная сия́ спаси́тельная нощь, / и светоза́рная, / светоно́снаго дне, / воста́ния су́щи провозве́стница, / в не́йже безле́тный Свет из гро́ба пло́тски всем возсия́."},
  {"id": "cu-che-0199", "section": "service", "who": "choir", "text": "Слава: Умертви́в Сын Твой смерть, Всенепоро́чная, / днесь всем сме́ртным пребыва́ющий живо́т во ве́ки веко́в дарова́, / Еди́н благослове́нный, / отце́в Бог и Препросла́вленный."},
  {"id": "cu-che-0200", "section": "service", "who": "choir", "text": "И ныне: Всем ца́рствуяй созда́нием, / быв челове́к, / всели́ся в Твою́, Богоблагода́тная, утро́бу, / и распя́тие претерпе́в и смерть, / воскре́се боголе́пно, / совозста́вив нас, я́ко всеси́лен. Катавасия:"},
  {"id": "cu-che-0201", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый: И тропарь:"},
  {"id": "cu-che-0202", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0203", "section": "service", "who": "choir", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-che-0204", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день, / Еди́н суббо́т Царь и Госпо́дь, / пра́здников пра́здник / и торжество́ есть торже́ств, / во́ньже благослови́м Христа́ во ве́ки. Припев:"},
  {"id": "cu-che-0205", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0206", "section": "service", "who": "choir", "text": "Прииди́те, но́ваго виногра́да рожде́ния, / Боже́ственнаго весе́лия, / в наро́читом дни Воскресе́ния, / Ца́рствия Христо́ва приобщи́мся, / пою́ще Его́ / я́ко Бо́га во ве́ки. Припев:"},
  {"id": "cu-che-0207", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-che-0208", "section": "service", "who": "choir", "text": "Возведи́ о́крест о́чи твои́, Сио́не, и виждь: / се бо приидо́ша к тебе́, / я́ко богосве́тлая свети́ла, / от за́пада, и се́вера, и мо́ря, / и восто́ка ча́да твоя́, / в тебе́ благословя́щая Христа́ во ве́ки. Припев:"},
  {"id": "cu-che-0209", "section": "service", "who": "choir", "text": "Пресвята́я Тро́ице, Бо́же наш, сла́ва Тебе́. Троичен:"},
  {"id": "cu-che-0210", "section": "service", "who": "choir", "text": "О́тче Вседержи́телю, и Сло́ве, и Ду́ше, / треми́ соединя́емое во Ипоста́сех Естество́, / Пресу́щественне и Пребоже́ственне, / в Тя крести́хомся, / и Тя благослови́м во вся ве́ки."},
  {"id": "cu-che-0211", "section": "service", "who": "choir", "text": "Благослови́м Отца́ и Сы́на и Свята́го Ду́ха, Го́спода."},
  {"id": "cu-che-0212", "section": "service", "who": "choir", "text": "Прии́де Тобо́ю в мир Госпо́дь, / Де́во Богоро́дице, / и чре́во а́дово расто́рг, / сме́ртным нам воскресе́ние дарова́, / те́мже благослови́м Его́ во ве́ки."},
  {"id": "cu-che-0213", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в, ами́нь."},
  {"id": "cu-che-0214", "section": "service", "who": "choir", "text": "Всю низложи́в сме́рти держа́ву / Сын Твой, Де́во, Свои́м воскресе́нием, / я́ко Бог кре́пкий совознесе́ нас и обожи́, / те́мже воспева́ем Его́ во ве́ки. Катавасия:"},
  {"id": "cu-che-0215", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день: И тропарь:"},
  {"id": "cu-che-0216", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-che-0217", "section": "service", "who": "choir", "text": "Песнь 9."},
  {"id": "cu-che-0218", "section": "service", "who": "deacon", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба, / Христа́ Жизнодавца."},
  {"id": "cu-che-0219", "section": "service", "who": "rubric", "text": "И первый лик ирмос:"},
  {"id": "cu-che-0220", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-che-0221", "section": "service", "who": "rubric", "text": "Таже вторый лик поет вторый припев:"},
  {"id": "cu-che-0222", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / во́лею страда́вша, и погребе́на, / и Воскре́сшаго тридне́вно от гро́ба. И ирмос:"},
  {"id": "cu-che-0223", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся:"},
  {"id": "cu-che-0224", "section": "service", "who": "rubric", "text": "Таже первый лик поет:"},
  {"id": "cu-che-0225", "section": "service", "who": "choir", "text": "Христо́с но́вая Па́сха, / Же́ртва жива́я, / А́гнец Бо́жий, / взе́мляй грехи́ ми́ра."},
  {"id": "cu-che-0226", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго, / о сладча́йшаго Твоего́ гла́са! / С на́ми бо нело́жно / обеща́лся еси́ бы́ти, / до сконча́ния ве́ка Христе́: / Его́же, ве́рнии, / утвержде́ние наде́жди иму́ще, ра́дуемся."},
  {"id": "cu-che-0227", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и тропарь."},
  {"id": "cu-che-0228", "section": "service", "who": "rubric", "text": "Таже первый лик поет припев:"},
  {"id": "cu-che-0229", "section": "service", "who": "choir", "text": "А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый: / лю́дие, весели́теся. И тропарь:"},
  {"id": "cu-che-0230", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-che-0231", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и тропарь."},
  {"id": "cu-che-0232", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-che-0233", "section": "service", "who": "choir", "text": "Возбуди́л еси́ усну́в ме́ртвыя от ве́ка, / ца́рски рыка́вый я́ко от Иу́ды лев. И тропарь:"},
  {"id": "cu-che-0234", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-che-0235", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-che-0236", "section": "service", "who": "choir", "text": "Магдали́на Мари́я притече́ ко гро́бу, / и Христа́ ви́девши, / я́ко вертогра́даря вопроша́ше."},
  {"id": "cu-che-0237", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая, Христе́! / О му́дросте, и Сло́ве Бо́жий, и си́ло! / Подава́й нам и́стее Тебе́ причаща́тися, / в невече́рнем дни Ца́рствия Твоего́."},
  {"id": "cu-che-0238", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-che-0239", "section": "service", "who": "choir", "text": "А́нгел облиста́яй жена́м вопия́ше: / преста́ните от слез, я́ко Христо́с воскре́се. И тропарь:"},
  {"id": "cu-che-0240", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-che-0241", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-che-0242", "section": "service", "who": "choir", "text": "Христо́с воскре́се, смерть попра́вый, / и ме́ртвыя воздви́гнувый, / лю́дие весели́теся. И тропарь:"},
  {"id": "cu-che-0243", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-che-0244", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-che-0245", "section": "service", "who": "choir", "text": "Днесь вся́ка тварь весели́тся и ра́дуется, / я́ко Христо́с воскре́се, и ад плени́ся. И тропарь:"},
  {"id": "cu-che-0246", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-che-0247", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-che-0248", "section": "service", "who": "choir", "text": "Днесь Влады́ка плени́ а́да, / воздви́гнувый ю́зники, я́же от ве́ка имя́ше лю́те одержи́мыя. И тропарь:"},
  {"id": "cu-che-0249", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-che-0250", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-che-0251", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Триипоста́снаго и Неразде́льнаго Божества́ держа́ву."},
  {"id": "cu-che-0252", "section": "service", "who": "choir", "text": "Согла́сно Де́во, Тебе́ блажи́м ве́рнии: / ра́дуйся, Две́ре Госпо́дня, / ра́дуйся, Гра́де одушевле́нный, / ра́дуйся, Ея́же ра́ди нам ны́не возсия́ свет, / из Тебе́ Рожде́ннаго из ме́ртвых Воскресе́ния."},
  {"id": "cu-che-0253", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-che-0254", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба."},
  {"id": "cu-che-0255", "section": "service", "who": "choir", "text": "Весели́ся и ра́дуйся боже́ственная Две́ре Све́та, / заше́дый бо Иису́с во гроб возсия́, / просия́в со́лнца светле́е, / и ве́рныя вся озари́в, / Богора́дованная Влады́чице."},
  {"id": "cu-che-0256", "section": "service", "who": "rubric", "text": "Таже оба лика, сошедшеся вкупе, поют припев:"},
  {"id": "cu-che-0257", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба, / Христа́ Жизнодавца. И ирмос:"},
  {"id": "cu-che-0258", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́. И тропарь:"},
  {"id": "cu-che-0259", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-che-0260", "section": "service", "who": "rubric", "text": "трижды. И ектениа."},
  {"id": "cu-che-0261", "section": "service", "who": "choir", "text": "Ексапостиларий. Самогласен:"},
  {"id": "cu-che-0262", "section": "service", "who": "choir", "text": "Пло́тию усну́в, / я́ко мертв, / Царю́ и Го́споди, / тридне́вен воскре́сл еси́, / Ада́ма воздви́г от тли, / и упраздни́в смерть, / Па́сха нетле́ния, / ми́ра спасе́ние. [Трижды.]"},
  {"id": "cu-che-0263", "section": "service", "who": "choir", "text": "На хвалитех, Всякое дыхание: Поставим стихи 4, и поем стихиры воскресны, глас 5: Стих:"},
  {"id": "cu-che-0264", "section": "service", "who": "choir", "text": "Хвали́те Его́ на си́лах Его́, / хвали́те Его́ по мно́жеству вели́чествия Его́."},
  {"id": "cu-che-0265", "section": "service", "who": "choir", "text": "Го́споди, запеча́тану гро́бу от беззако́нников, / проше́л еси́ из гро́ба, / я́коже роди́лся еси́ от Богоро́дицы: / не уразуме́ша, ка́ко воплоти́лся еси́, безпло́тнии Твои́ а́нгели: / не чу́вствоваша, когда́ воскре́сл еси́, стрегу́щии Тя во́ини. / Обоя́ бо запечатле́стася испыту́ющим, / яви́шася же чудеса́ кла́няющимся ве́рою та́инству: / е́же воспева́ющим, / возда́ждь нам ра́дость и ве́лию ми́лость. Стих:"},
  {"id": "cu-che-0266", "section": "service", "who": "choir", "text": "Хвали́те Его́ во гла́се тру́бнем, / хвалите Его́ во псалти́ри и гу́слех."},
  {"id": "cu-che-0267", "section": "service", "who": "choir", "text": "Го́споди, вереи́ ве́чныя сокруши́в, / и у́зы растерза́в, от гро́ба воскре́сл еси́, / оста́вль Твоя́ погреба́льная, / во свиде́тельство и́стиннаго тридне́внаго Твоего́ погребе́ния: / и предвари́л еси́ в Галиле́и, в пеще́ре стрего́мый. / Ве́лия Твоя́ ми́лость, Непостижи́ме Спа́се, / поми́луй и спаси́ нас. Стих:"},
  {"id": "cu-che-0268", "section": "service", "who": "choir", "text": "Хвали́те Его́ в тимпа́не и ли́це, / хвали́те Его́ во стру́нах и орга́не."},
  {"id": "cu-che-0269", "section": "service", "who": "choir", "text": "Го́споди, жены́ теко́ша на гроб, / ви́дети Тя, Христа́, нас ра́ди пострада́вшаго, / и прише́дша, обрето́ша а́нгела на ка́мени седя́ща, / стра́хом отва́льшемся, / и к ним возопи́, глаго́ля: / воскре́се Госпо́дь, рцы́те ученико́м, / я́ко воскре́се от ме́ртвых, / спаса́яй ду́ши на́ша. Стих:"},
  {"id": "cu-che-0270", "section": "service", "who": "choir", "text": "Хвали́те Его́ в кимва́лех доброгла́сных, хвали́те Его́ в кимва́лех восклица́ния, / вся́кое дыха́ние да хва́лит Го́спода."},
  {"id": "cu-che-0271", "section": "service", "who": "choir", "text": "Го́споди, я́коже изше́л еси́ от запеча́таннаго гро́ба, / та́ко вшел еси́ и две́рем заключе́ным ко ученико́м Твои́м, / показу́я им теле́сная страда́ния, / я́же подъя́л еси́, Спа́се Долготерпели́вый: / я́ко от се́мене Дави́дова я́звы претерпе́л еси́, / я́ко Сын же Бо́жий, мiр свободи́л еси́. / Ве́лия Твоя́ ми́лость, Непостижи́ме Спа́се, / поми́луй и спаси́ нас."},
  {"id": "cu-che-0272", "section": "service", "who": "choir", "text": "И стихиры Пасхи с припевы их, глас 5. Стих:"},
  {"id": "cu-che-0273", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, / и расточа́тся врази́ Его́."},
  {"id": "cu-che-0274", "section": "service", "who": "choir", "text": "Па́сха / свяще́нная нам днесь показа́ся; / Па́сха но́ва свята́я; / Па́сха та́инственная; / Па́сха всечестна́я. / Па́сха Христо́с Изба́витель; / Па́сха непоро́чная; / Па́сха вели́кая; / Па́сха ве́рных. / Па́сха две́ри ра́йския нам отверза́ющая. / Па́сха всех освяща́ющая ве́рных. Стих:"},
  {"id": "cu-che-0275", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, / да исче́знут."},
  {"id": "cu-che-0276", "section": "service", "who": "choir", "text": "Прииди́те / от виде́ния жены́ благове́стницы, / и Сио́ну рцы́те: / приими́ / от нас ра́дости благове́щения, Воскресе́ния Христо́ва: / красу́йся, лику́й / и ра́дуйся, Иерусали́ме, / Царя́ Христа́ узре́в из гро́ба, / я́ко жениха́ происходя́ща. Стих:"},
  {"id": "cu-che-0277", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся."},
  {"id": "cu-che-0278", "section": "service", "who": "choir", "text": "Мироно́сицы жены́, / у́тру глубоку́, / предста́вша гро́бу Живода́вца, / обрето́ша А́нгела / на ка́мени седя́ща, / и той провеща́в им, / си́це глаго́лаше: / что и́щете Жива́го с ме́ртвыми; / что пла́чете Нетле́ннаго во тли? / Ше́дше, пропове́дите ученико́м Его́. Стих:"},
  {"id": "cu-che-0279", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори Госпо́дь, / возра́дуемся и возвесели́мся в онь."},
  {"id": "cu-che-0280", "section": "service", "who": "choir", "text": "Па́сха кра́сная, / Па́сха, Госпо́дня Па́сха! / Па́сха всечестна́я / нам возсия́. Па́сха, / ра́достию друг дру́га обы́мем. / О Па́сха! / Избавле́ние ско́рби, / и́бо из гро́ба днесь, / я́ко от черто́га / возсия́в Христо́с, / жены́ ра́дости испо́лни, глаго́ля: / пропове́дите апо́столом."},
  {"id": "cu-che-0281", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0282", "section": "service", "who": "choir", "text": "Таже настоящий тропарь, во глас 5, трижды:"},
  {"id": "cu-che-0283", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0284", "section": "service", "who": "choir", "text": "Обычный отпуст. И лития вне обители. Часы же по обычаю Пасхи."},
  {"id": "cu-che-0285", "section": "service", "who": "choir", "text": "НА ЛИТУРГИИ"},
  {"id": "cu-che-0286", "section": "service", "who": "rubric", "text": "Наченшу диакону:"},
  {"id": "cu-che-0287", "section": "service", "who": "deacon", "text": "Благослови́ влады́ко."},
  {"id": "cu-che-0288", "section": "service", "who": "rubric", "text": "Настоятелю же возгласившу:"},
  {"id": "cu-che-0289", "section": "service", "who": "deacon", "text": "Благослове́но Ца́рство Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в. И мы:"},
  {"id": "cu-che-0290", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-che-0291", "section": "service", "who": "deacon", "text": "Настоятель поет с прочими служители во святом олтаре:"},
  {"id": "cu-che-0292", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в. Трижды."},
  {"id": "cu-che-0293", "section": "service", "who": "deacon", "text": "И лики тойжде, трижды."},
  {"id": "cu-che-0294", "section": "service", "who": "choir", "text": "Настоятель глаголет припевы: Первый стих:"},
  {"id": "cu-che-0295", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-che-0296", "section": "service", "who": "choir", "text": "И на кийждо стих мы поем тропарь весь по единожды: Тропарь:"},
  {"id": "cu-che-0297", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Вторый стих:"},
  {"id": "cu-che-0298", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-che-0299", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-che-0300", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-che-0301", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-che-0302", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-che-0303", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-che-0304", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-che-0305", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-che-0306", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-che-0307", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-che-0308", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-che-0309", "section": "service", "who": "rubric", "text": "Таже настоятель поет вышшим гласом:"},
  {"id": "cu-che-0310", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. Мы же:"},
  {"id": "cu-che-0311", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0312", "section": "service", "who": "choir", "text": "Посем глаголет диакон ектению великую. По ектении же и по возгласе:"},
  {"id": "cu-che-0313", "section": "service", "who": "choir", "text": "Антифон первый, псалом 65, глас 2. Стих 1:"},
  {"id": "cu-che-0314", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви / вся земля́. Припев:"},
  {"id": "cu-che-0315", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-che-0316", "section": "service", "who": "rubric", "text": "И другий лик тойжде стих:"},
  {"id": "cu-che-0317", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви вся земля́, / по́йте же и́мени Его́, дади́те сла́ву хвале́ Его́. Припев:"},
  {"id": "cu-che-0318", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 2:"},
  {"id": "cu-che-0319", "section": "service", "who": "choir", "text": "Рцы́те Бо́гу: коль стра́шна дела́ Твоя́, / во мно́жестве си́лы Твоея́ со́лжут Тебе́ врази́ Твои́. Припев:"},
  {"id": "cu-che-0320", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 3:"},
  {"id": "cu-che-0321", "section": "service", "who": "choir", "text": "Вся земля́ да покло́нится Тебе́, / и пое́т Тебе́, да пое́т же и́мени Твоему́ Вы́шний. Припев:"},
  {"id": "cu-che-0322", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-che-0323", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-che-0324", "section": "service", "who": "rubric", "text": "Купно оба лика вышшим гласом:"},
  {"id": "cu-che-0325", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-che-0326", "section": "service", "who": "choir", "text": "Таже, ектениа малая."},
  {"id": "cu-che-0327", "section": "service", "who": "choir", "text": "Антифон вторый, псалом 66, глас тойже. Стих 1:"},
  {"id": "cu-che-0328", "section": "service", "who": "choir", "text": "Бо́же уще́дри ны / и благослови́ ны. Припев:"},
  {"id": "cu-che-0329", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-che-0330", "section": "service", "who": "rubric", "text": "Другая страна, тойже стих:"},
  {"id": "cu-che-0331", "section": "service", "who": "choir", "text": "Бо́же, уще́дри ны и благослови́ ны, / просвети лице Твое́ на ны и поми́луй ны. Припев:"},
  {"id": "cu-che-0332", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 2:"},
  {"id": "cu-che-0333", "section": "service", "who": "choir", "text": "Да позна́ем на земли́ путь Твой, / во всех язы́цех спасе́ние Твое́. Припев:"},
  {"id": "cu-che-0334", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 3:"},
  {"id": "cu-che-0335", "section": "service", "who": "choir", "text": "Да испове́дятся Тебе́ лю́дие, Бо́же, / да испове́дятся Тебе́ лю́дие вси. Припев:"},
  {"id": "cu-che-0336", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-che-0337", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-che-0338", "section": "service", "who": "rubric", "text": "Вкупе два лика:"},
  {"id": "cu-che-0339", "section": "service", "who": "choir", "text": "Единоро́дный Сы́не и Сло́ве Бо́жий, Безсме́ртен Сый / и изво́ливый спасе́ния на́шего ра́ди / воплоти́тися от Святы́я Богоро́дицы и Присноде́вы Мари́и, / непрело́жно вочелове́чивыйся, / распны́йся же, Христе́ Бо́же, сме́ртию смерть попра́вый, / Еди́н Сый Святы́я Тро́ицы, / спрославля́емый Отцу́ и Свято́му Ду́ху, спаси́ нас."},
  {"id": "cu-che-0340", "section": "service", "who": "choir", "text": "Таже, ектениа."},
  {"id": "cu-che-0341", "section": "service", "who": "choir", "text": "Антифон 3-й, псалом 67, глас 5. Стих 1:"},
  {"id": "cu-che-0342", "section": "service", "who": "choir", "text": "Да воскре́снет Бог / и расточа́тся врази́ Его́."},
  {"id": "cu-che-0343", "section": "service", "who": "choir", "text": "Тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0344", "section": "service", "who": "rubric", "text": "Другая страна, той же стих:"},
  {"id": "cu-che-0345", "section": "service", "who": "choir", "text": "Да воскре́снет Бог и расточа́тся врази́ Его́, / и да бежа́т от лица́ Его́ ненави́дящии Его́. Тропарь:"},
  {"id": "cu-che-0346", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 2:"},
  {"id": "cu-che-0347", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-che-0348", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 3:"},
  {"id": "cu-che-0349", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от лица́ Бо́жия, / а пра́ведницы да возвеселя́тся, да возра́дуются пред Бо́гом. Тропарь:"},
  {"id": "cu-che-0350", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-che-0351", "section": "service", "who": "rubric", "text": "И бывает вход. И возглашает диакон, аще есть, аще же ни, иерей:"},
  {"id": "cu-che-0352", "section": "service", "who": "deacon", "text": "Прему́дрость, про́сти."},
  {"id": "cu-che-0353", "section": "service", "who": "deacon", "text": "Мы же входное: В це́рквах благослови́те Бо́га, / Го́спода от исто́чник Изра́илевых."},
  {"id": "cu-che-0354", "section": "service", "who": "deacon", "text": "И поем тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0355", "section": "service", "who": "deacon", "text": "Ипакои, глас 4: Предвари́вшия у́тро, я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-che-0356", "section": "service", "who": "deacon", "text": "Слава, и ныне: кондак, глас 8: А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко Победи́тель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся! / И Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-che-0357", "section": "service", "who": "deacon", "text": "Вместо же Трисвятаго: Ели́цы во Христа́ крести́стеся, / во Христа́ облеко́стеся: / аллилу́иа."},
  {"id": "cu-che-0358", "section": "service", "who": "deacon", "text": "Прокимен, глас 3: По́йте Бо́гу на́шему, по́йте, / по́йте Царе́ви на́шему, по́йте. Стих:"},
  {"id": "cu-che-0359", "section": "service", "who": "deacon", "text": "Вси язы́цы восплещи́те рука́ми, воскли́кните Бо́гу гла́сом ра́дования."},
  {"id": "cu-che-0360", "section": "service", "who": "deacon", "text": "Деяния святых Апостол, зачало 6."},
  {"id": "cu-che-0361", "section": "service", "who": "deacon", "text": "Во дни о́ны, рече́ Петр к лю́дем: пока́йтеся, и да крести́тся ки́йждо вас во и́мя Иису́са Христа́ во оставле́ние грехо́в, и прии́мете дар Свята́го Ду́ха. Вам бо есть обетова́ние и ча́дом ва́шим и всем да́льним, ели́ки а́ще призове́т Госпо́дь Бог наш. И ины́ми словесы́ мно́жайшими засвиде́тельствоваше и моля́ше я́, глаго́ля: спаси́теся от ро́да стропти́ваго сего́. И́же у́бо любе́зно прия́ша сло́во его́, крести́шася, и приложи́шася в день той душ я́ко три ты́сящи. Бя́ху же терпя́ще во уче́нии Апо́стол и во обще́нии и в преломле́нии хле́ба и в моли́твах. Бысть же на вся́кой души́ страх: мно́га бо чудеса́ и зна́мения Апо́столы бы́ша во Иерусали́ме."},
  {"id": "cu-che-0362", "section": "service", "who": "deacon", "text": "Аллилуиа, глас 4: Стих:"},
  {"id": "cu-che-0363", "section": "service", "who": "deacon", "text": "Наляцы́ и успева́й, и ца́рствуй и́стины ра́ди и кро́тости, и пра́вды. Стих:"},
  {"id": "cu-che-0364", "section": "service", "who": "deacon", "text": "Возлюби́л еси́ пра́вду, и возненави́дел еси́ беззако́ние."},
  {"id": "cu-che-0365", "section": "service", "who": "deacon", "text": "Евангелие от Иоанна, зачало 8."},
  {"id": "cu-che-0366", "section": "service", "who": "deacon", "text": "Во вре́мя о́но, челове́к не́кий бе от фарисе́й, Никоди́м и́мя ему́, князь жидо́вский. Сей прии́де ко Иису́су но́щию и рече́ Ему́: Равви́, вем, я́ко от Бо́га прише́л еси́ учи́тель, никто́же бо мо́жет зна́мений сих твори́ти, и́хже Ты твори́ши, а́ще не бу́дет Бог с ним. Отвеща́ Иису́с и рече́ ему́: ами́нь, ами́нь глаго́лю тебе́: а́ще кто не роди́тся свы́ше, не мо́жет ви́дети Ца́рствия Бо́жия. Глаго́ла к Нему́ Никоди́м: ка́ко мо́жет челове́к роди́тися стар сый? Еда́ мо́жет второ́е вни́ти во утро́бу ма́тере своея́ и роди́тися? Отвеща́ Иису́с: ами́нь, ами́нь глаго́лю тебе́, а́ще кто не роди́тся водо́ю и Ду́хом, не мо́жет вни́ти во Ца́рствие Бо́жие. Рожде́нное от пло́ти плоть есть, и рожде́нное от Ду́ха дух есть. Не диви́ся, я́ко рех ти, подоба́ет вам роди́тися свы́ше. Дух, иде́же хо́щет, ды́шет, и глас его́ слы́шиши, но не ве́си, отку́ду прихо́дит и ка́мо и́дет, та́ко есть всяк челове́к рожде́нный от Ду́ха. Отвеща́ Никоди́м и рече́ Ему́: ка́ко мо́гут сия́ бы́ти? Отвеща́ Иису́с и рече́ ему́: ты еси́ учи́тель Изра́илев, и сих ли не ве́си? Ами́нь, ами́нь глаго́лю тебе́, я́ко, е́же ве́мы, глаго́лем, и е́же ви́дехом, свиде́тельствуем, и свиде́тельства На́шего не прие́млете. А́ще земна́я реко́х вам, и не ве́руете, ка́ко, а́ще реку́ вам небе́сная, ве́руете? И никто́же взы́де на не́бо, то́кмо сше́дый с небесе́ Сын Челове́ческий, сый на небеси́. И я́коже Моисе́й вознесе́ змию́ в пусты́ни, та́ко подоба́ет вознести́ся Сы́ну Челове́ческому, да всяк ве́руяй в Онь не поги́бнет, но и́мать живо́т ве́чный."},
  {"id": "cu-che-0367", "section": "service", "who": "deacon", "text": "И бывает по чину Божественная Литургиа Златоустаго."},
  {"id": "cu-che-0368", "section": "service", "who": "deacon", "text": "Вместо же Достойно: поем: А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый, / лю́дие, весели́теся."},
  {"id": "cu-che-0369", "section": "service", "who": "rubric", "text": "Таже ирмос, глас 1:"},
  {"id": "cu-che-0370", "section": "service", "who": "deacon", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-che-0371", "section": "service", "who": "deacon", "text": "Причастный: Те́ло Христо́во приими́те, / исто́чника безсме́ртнаго вкуси́те. / Аллилу́иа. трижды."},
  {"id": "cu-che-0372", "section": "service", "who": "rubric", "text": "Егда же настоятель глаголет:"},
  {"id": "cu-che-0373", "section": "service", "who": "deacon", "text": "Со стра́хом Бо́жиим и ве́рою приступи́те."},
  {"id": "cu-che-0374", "section": "service", "who": "rubric", "text": "Мы вместо, Благословен грядый во имя Господне: поем:"},
  {"id": "cu-che-0375", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-che-0376", "section": "service", "who": "rubric", "text": "единожды. Настоятель глаголет:"},
  {"id": "cu-che-0377", "section": "service", "who": "deacon", "text": "Спаси́ Бо́же лю́ди Твоя́: И мы:"},
  {"id": "cu-che-0378", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-che-0379", "section": "service", "who": "rubric", "text": "единожды. Егда же изглаголет иерей:"},
  {"id": "cu-che-0380", "section": "service", "who": "priest", "text": "Всегда́ ны́не и при́сно: И мы:"},
  {"id": "cu-che-0381", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-che-0382", "section": "service", "who": "rubric", "text": "единожды. Посем ектениа. Вместо же, Буди имя Господне: и вместо псалма, Благословлю Господа: поем:"},
  {"id": "cu-che-0383", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-che-0384", "section": "service", "who": "rubric", "text": "дванадесять, и множае: дондеже анафора от игумена раздастся. Таже настоятель,"},
  {"id": "cu-che-0385", "section": "service", "who": "priest", "text": "Благослове́ние Госпо́дне на вас:"},
  {"id": "cu-che-0386", "section": "service", "who": "choir", "text": "Ами́нь."},
  {"id": "cu-che-0387", "section": "service", "who": "rubric", "text": "Посем настоятель вместо, Слава Тебе Христе Боже: поет:"},
  {"id": "cu-che-0388", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в."},
  {"id": "cu-che-0389", "section": "service", "who": "rubric", "text": "И лик:"},
  {"id": "cu-che-0390", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-che-0391", "section": "service", "who": "rubric", "text": "Посем настоятель глаголет отпуст со Крестом по обычаю."},
];

